  (* [comment removed for export] *)
  Lemma ret_run : forall regs (M : word -> option byte),
    getr regs 1 = ret ->
    exists regs',
      msteps MSEGS (mkst regs (PC 0xf4) M rom) (mkst regs' ret M rom)
